-- Lig bilgisi: puan durumu, gol ve asist krallığı
create table if not exists public.league_table (team text primary key, pos int not null, played int not null, won int not null, drawn int not null, lost int not null, gf int not null, ga int not null, points int not null, form text, after_week int, updated_at timestamptz not null default now());
create table if not exists public.top_scorers (id bigint generated always as identity primary key, name text not null, team text not null, goals int not null);
create table if not exists public.top_assists (id bigint generated always as identity primary key, name text not null, team text not null, assists int not null);
-- RLS: herkes okur, admin yazar
delete from public.top_scorers; delete from public.top_assists; delete from public.league_table;
